out = {}
for ch, (tops, rx) in RULES.items():
    R = re.compile(rx, re.I)
    ks = [q['key'] for q in B if q['tid'] in tops and R.search(q['q'] + ' ' + str(q['a']))]
    out[ch] = ks
taken = {}
# сначала узкие главы, потом широкие: вопрос достаётся самой специфичной подходящей главе
ORDER = [10, 9, 8, 16, 17, 15, 13, 14, 12, 11, 20, 19, 18, 25, 24, 23, 22, 21, 26, 30, 28, 27, 29, 31, 33, 32]
for ch in ORDER + [c for c in sorted(out) if c not in ORDER]:
    out[ch] = [k for k in out[ch] if k not in taken]; [taken.setdefault(k, ch) for k in out[ch]]
lines = ['/* Вопросы экзамена к главам 8–33: подобраны по темам базы и ключевым словам (tools/exam_auto.py) */']
for ch in sorted(out): lines.append('if (CONTENT[%d] && !CONTENT[%d].exam.length) CONTENT[%d].exam = %s;' % (ch, ch, ch, json.dumps(out[ch])))
open(sys.argv[2], 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
for ch in sorted(out): print(ch, len(out[ch]))
miss = [q['key'] for q in B if q['tid'] == 4 and q['key'] not in taken]; print('topic4 not assigned:', len(miss), miss[:20])
